class Solution {
public:
    bool canDistribute(vector<int>& nums, vector<int>& quantity) {
        unordered_map<int,int> cnt;
        for (int x : nums) cnt[x]++;
        vector<int> freq;
        freq.reserve(cnt.size());
        for (auto& p : cnt) freq.push_back(p.second);
        sort(freq.rbegin(), freq.rend());
        sort(quantity.rbegin(), quantity.rend());
        int m = quantity.size();
        int full = (1 << m) - 1;
        vector<int> sm(full + 1, 0);
        for (int mask = 1; mask <= full; mask++)
            sm[mask] = sm[mask & (mask - 1)] + quantity[__builtin_ctz(mask)];
        vector<char> dp(full + 1, 0);
        dp[0] = 1;
        for (int f : freq) {
            for (int mask = full; mask >= 0; mask--) {
                if (!dp[mask]) continue;
                int rem = full & ~mask;
                for (int sub = rem; ; sub = (sub - 1) & rem) {
                    if (sm[sub] <= f) dp[mask | sub] = 1;
                    if (sub == 0) break;
                }
            }
            if (dp[full]) return true;
        }
        return dp[full] != 0;
    }
};
